import { redirect } from 'next/navigation'

type ContactField = 'name' | 'email' | 'message'

export type ContactFormFeedback =
  | { kind: 'missing'; fields: ContactField[] }
  | { kind: 'sent' }

type ContactFormProps = {
  feedback?: ContactFormFeedback
}

async function submitContact(formData: FormData) {
  'use server'

  const rawName = formData.get('name')
  const rawEmail = formData.get('email')
  const rawMessage = formData.get('message')

  const name = typeof rawName === 'string' ? rawName.trim() : ''
  const email = typeof rawEmail === 'string' ? rawEmail.trim() : ''
  const message = typeof rawMessage === 'string' ? rawMessage.trim() : ''

  const missing: ContactField[] = []
  if (!name) missing.push('name')
  if (!email) missing.push('email')
  if (!message) missing.push('message')

  if (missing.length > 0) {
    const missingParam = missing.join(',')
    redirect(`/?contact=err&missing=${encodeURIComponent(missingParam)}`)
  }

  console.log('Contact message:', { name, email, message })

  redirect('/?contact=ok')
}

const fieldMessages: Record<ContactField, string> = {
  name: 'Name is required.',
  email: 'Email is required.',
  message: 'Message is required.',
}

export default function ContactForm({ feedback }: ContactFormProps) {
  const fieldErrors: Partial<Record<ContactField, string>> =
    feedback?.kind === 'missing'
      ? Object.fromEntries(
          feedback.fields.map((field) => [field, fieldMessages[field]])
        )
      : {}

  if (feedback?.kind === 'sent') {
    return (
      <div style={{ marginTop: '2rem' }}>
        <h2>Contact Us</h2>
        <p role="status">Thanks — your message was received.</p>
      </div>
    )
  }

  return (
    <div style={{ marginTop: '2rem' }}>
      <h2>Contact Us</h2>

      <form action={submitContact} noValidate>
        <div style={{ marginBottom: '0.75rem' }}>
          <label htmlFor="contact-name" style={{ display: 'block' }}>
            Name
          </label>
          <input
            id="contact-name"
            name="name"
            type="text"
            autoComplete="name"
            aria-invalid={Boolean(fieldErrors.name)}
            aria-describedby={
              fieldErrors.name ? 'contact-name-error' : undefined
            }
          />
          {fieldErrors.name ? (
            <p id="contact-name-error" role="alert" style={{ color: 'crimson' }}>
              {fieldErrors.name}
            </p>
          ) : null}
        </div>

        <div style={{ marginBottom: '0.75rem' }}>
          <label htmlFor="contact-email" style={{ display: 'block' }}>
            Email
          </label>
          <input
            id="contact-email"
            name="email"
            type="email"
            autoComplete="email"
            aria-invalid={Boolean(fieldErrors.email)}
            aria-describedby={
              fieldErrors.email ? 'contact-email-error' : undefined
            }
          />
          {fieldErrors.email ? (
            <p
              id="contact-email-error"
              role="alert"
              style={{ color: 'crimson' }}
            >
              {fieldErrors.email}
            </p>
          ) : null}
        </div>

        <div style={{ marginBottom: '0.75rem' }}>
          <label htmlFor="contact-message" style={{ display: 'block' }}>
            Message
          </label>
          <textarea
            id="contact-message"
            name="message"
            rows={5}
            aria-invalid={Boolean(fieldErrors.message)}
            aria-describedby={
              fieldErrors.message ? 'contact-message-error' : undefined
            }
          />
          {fieldErrors.message ? (
            <p
              id="contact-message-error"
              role="alert"
              style={{ color: 'crimson' }}
            >
              {fieldErrors.message}
            </p>
          ) : null}
        </div>

        <button type="submit">Send message</button>
      </form>
    </div>
  )
}

