'use client'

import { useActionState } from 'react'

type ContactFormState =
  | { status: 'idle' }
  | {
      status: 'error'
      fieldErrors: Partial<Record<'name' | 'email' | 'message', string>>
    }
  | { status: 'success'; message: string }

const initialState: ContactFormState = { status: 'idle' }

async function submitContact(
  _prevState: ContactFormState,
  formData: FormData
): Promise<ContactFormState> {
  'use server'

  const rawName = formData.get('name')
  const rawEmail = formData.get('email')
  const rawMessage = formData.get('message')

  const name =
    typeof rawName === 'string' ? rawName.trim() : ''
  const email =
    typeof rawEmail === 'string' ? rawEmail.trim() : ''
  const message =
    typeof rawMessage === 'string' ? rawMessage.trim() : ''

  const fieldErrors: Partial<Record<'name' | 'email' | 'message', string>> =
    {}

  if (!name) {
    fieldErrors.name = 'Name is required.'
  }
  if (!email) {
    fieldErrors.email = 'Email is required.'
  }
  if (!message) {
    fieldErrors.message = 'Message is required.'
  }

  if (Object.keys(fieldErrors).length > 0) {
    return { status: 'error', fieldErrors }
  }

  console.log('Contact message:', { name, email, message })

  return {
    status: 'success',
    message: 'Thanks — your message was received.',
  }
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(
    submitContact,
    initialState
  )

  return (
    <div style={{ marginTop: '2rem' }}>
      <h2>Contact Us</h2>

      {state.status === 'success' ? (
        <p role="status">{state.message}</p>
      ) : (
        <form action={formAction} noValidate>
          <div style={{ marginBottom: '0.75rem' }}>
            <label htmlFor="contact-name" style={{ display: 'block' }}>
              Name
            </label>
            <input
              id="contact-name"
              name="name"
              type="text"
              autoComplete="name"
              aria-invalid={Boolean(state.fieldErrors?.name)}
              aria-describedby={
                state.fieldErrors?.name ? 'contact-name-error' : undefined
              }
            />
            {state.fieldErrors?.name ? (
              <p id="contact-name-error" role="alert" style={{ color: 'crimson' }}>
                {state.fieldErrors.name}
              </p>
            ) : null}
          </div>

          <div style={{ marginBottom: '0.75rem' }}>
            <label htmlFor="contact-email" style={{ display: 'block' }}>
              Email
            </label>
            <input
              id="contact-email"
              name="email"
              type="email"
              autoComplete="email"
              aria-invalid={Boolean(state.fieldErrors?.email)}
              aria-describedby={
                state.fieldErrors?.email ? 'contact-email-error' : undefined
              }
            />
            {state.fieldErrors?.email ? (
              <p
                id="contact-email-error"
                role="alert"
                style={{ color: 'crimson' }}
              >
                {state.fieldErrors.email}
              </p>
            ) : null}
          </div>

          <div style={{ marginBottom: '0.75rem' }}>
            <label htmlFor="contact-message" style={{ display: 'block' }}>
              Message
            </label>
            <textarea
              id="contact-message"
              name="message"
              rows={5}
              aria-invalid={Boolean(state.fieldErrors?.message)}
              aria-describedby={
                state.fieldErrors?.message ? 'contact-message-error' : undefined
              }
            />
            {state.fieldErrors?.message ? (
              <p
                id="contact-message-error"
                role="alert"
                style={{ color: 'crimson' }}
              >
                {state.fieldErrors.message}
              </p>
            ) : null}
          </div>

          <button type="submit" disabled={isPending}>
            {isPending ? 'Sending…' : 'Send message'}
          </button>
        </form>
      )}
    </div>
  )
}

