import ContactForm, {
  type ContactFormFeedback,
} from './ContactForm'

// Example of existing server action
async function updateProfile(formData: FormData) {
  'use server'

  const name = formData.get('name') as string
  const email = formData.get('email') as string

  // Simulate database update
  console.log('Updating profile:', { name, email })
}

function parseContactFeedback(
  searchParams: Record<string, string | string[] | undefined>
): ContactFormFeedback | undefined {
  const contact = searchParams.contact
  const contactStr = Array.isArray(contact) ? contact[0] : contact
  if (contactStr === 'ok') {
    return { kind: 'sent' }
  }
  if (contactStr === 'err') {
    const missing = searchParams.missing
    const missingStr = Array.isArray(missing) ? missing[0] : missing
    if (!missingStr) return undefined
    const fields = missingStr
      .split(',')
      .filter((f): f is 'name' | 'email' | 'message' =>
        f === 'name' || f === 'email' || f === 'message'
      )
    if (fields.length === 0) return undefined
    return { kind: 'missing', fields }
  }
  return undefined
}

export default async function Page({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>
}) {
  const sp = await searchParams
  const contactFeedback = parseContactFeedback(sp)

  return (
    <div>
      <h1>Dashboard</h1>

      <form action={updateProfile}>
        <input name="name" placeholder="Name" required />
        <input name="email" type="email" placeholder="Email" required />
        <button type="submit">Update Profile</button>
      </form>

      <ContactForm feedback={contactFeedback} />
    </div>
  )
}

