            id="contact-email"
            name="email"
            type="email"
            autoComplete="email"
            aria-invalid={Boolean(fieldErrors.email)}
            aria-describedby={
              fieldErrors.email ? 'contact-email-error' : undefined
            }
          />
          {fieldErrors.email ? (
            <p
              id="contact-email-error"
              role="alert"
              style={{ color: 'crimson' }}
            >
              {fieldErrors.email}
            </p>
          ) : null}
        </div>

        <div style={{ marginBottom: '0.75rem' }}>
